import datetime
import math
import re
import polars as pl

NULL_VALUES = {"", "n/a", "na", "-", "null", "none"}

def _clean_str(col: pl.Expr) -> pl.Expr:
    s = col.str.strip_chars()
    return pl.when(s.is_in(list(NULL_VALUES)) | s.str.to_lowercase().is_in(list(NULL_VALUES))).then(None).otherwise(s)

def transform(raw: pl.DataFrame) -> pl.DataFrame:
    return raw.select(
        contact_id=_clean_str(pl.col("id")).str.to_uppercase(),
        full_name=(
            _clean_str(pl.col("name.first")).fill_null("") + " " + _clean_str(pl.col("name.last")).fill_null("")
        ).str.strip_chars().replace("", None),
        email=_clean_str(pl.col("contact.email")).str.to_lowercase(),
        phone=_clean_str(pl.col("contact.phone")),
        company=_clean_str(pl.col("org.name")),
        created_on=_clean_str(pl.col("created_at")).str.strptime(pl.Datetime, format="%Y-%m-%dT%H:%M:%SZ", strict=False).dt.date(),
        lifetime_value=_clean_str(pl.col("stats.ltv")).cast(pl.Float64, strict=False),
    )
